add_filter( 'woocommerce_available_payment_gateways', 'perfectpixel_disable_gateway_by_shipping' );

function perfectpixel_disable_gateway_by_shipping( $gateways ) {
	if ( is_admin() || ! WC()->session ) {
		return $gateways;
	}
	$chosen  = (array) WC()->session->get( 'chosen_shipping_methods', array() );
	$targets = array_filter( array_map( 'trim', explode( ',', '{{gateway_shipping_methods}}' ) ) );

	foreach ( $chosen as $rate_id ) {
		$method_id = strtok( (string) $rate_id, ':' );
		if ( in_array( $rate_id, $targets, true ) || in_array( $method_id, $targets, true ) ) {
			foreach ( array_filter( array_map( 'trim', explode( ',', '{{gateway_shipping_disable}}' ) ) ) as $id ) {
				unset( $gateways[ $id ] );
			}
			break;
		}
	}
	return $gateways;
}
